//! Per-champion bookkeeping: who am I, gold now and lifetime, gems carried and
//! tributed, and which shards/emblems I own.
//!
//! Lifetime gold matters because it is the first tiebreak at round 2000. The
//! SDK only exposes current gold, so the ledger reconstructs earnings from
//! gold deltas plus what our own executor reports spending.

use crate::bc_core::champion::ChampionKind;

/// Item families in SDK `ItemType` order (`id = family*6 + stat*2 + emblem`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum Family {
    Monster = 0,
    Power = 1,
    Durability = 2,
    Treasure = 3,
    Jungle = 4,
    Home = 5,
    Bruiser = 6,
    // Engine 2.0.0 families.
    Tribute = 7,
    Capture = 8,
    Prospector = 9,
    Hunter = 10,
    Skirmish = 11,
    Greed = 12,
    Collectors = 13,
}

impl Family {
    pub const ALL: [Self; 14] = [
        Self::Monster,
        Self::Power,
        Self::Durability,
        Self::Treasure,
        Self::Jungle,
        Self::Home,
        Self::Bruiser,
        Self::Tribute,
        Self::Capture,
        Self::Prospector,
        Self::Hunter,
        Self::Skirmish,
        Self::Greed,
        Self::Collectors,
    ];

    /// Shards that combine into one emblem of this family (Greed: 25 shards, 750 gold).
    #[must_use]
    pub const fn shards_per_emblem(self) -> u32 {
        match self {
            Self::Greed => 25,
            _ => SHARDS_PER_EMBLEM,
        }
    }

    /// Shards' worth of stats one emblem gives (Power +1 on completion, Greed 35 for 25).
    #[must_use]
    pub const fn stat_shards_per_emblem(self) -> u32 {
        match self {
            Self::Power => 6,
            Self::Greed => 35,
            _ => SHARDS_PER_EMBLEM,
        }
    }
}

/// Stat order inside a family in SDK `ItemType` order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum Stat {
    Strength = 0,
    Focus = 1,
    Health = 2,
}

impl Stat {
    pub const ALL: [Self; 3] = [Self::Strength, Self::Focus, Self::Health];
}

/// Number of `cambc::ItemType` values.
pub const ITEM_TYPES: usize = 84;
pub const SHARD_COST: u32 = 30;
pub const SHARDS_PER_EMBLEM: u32 = 5;

/// SDK item id for a shard or emblem.
#[must_use]
pub const fn item_id(family: Family, stat: Stat, emblem: bool) -> u8 {
    family as u8 * 6 + stat as u8 * 2 + emblem as u8
}

#[must_use]
pub fn decode_item(id: u8) -> Option<(Family, Stat, bool)> {
    if id as usize >= ITEM_TYPES {
        return None;
    }
    let family = Family::ALL[(id / 6) as usize];
    let stat = Stat::ALL[((id % 6) / 2) as usize];
    Some((family, stat, id % 2 == 1))
}

/// One turn's self-observation, gathered by the SDK adapter.
#[derive(Clone, Debug, PartialEq)]
pub struct SelfObs {
    pub round: u32,
    pub alive: bool,
    pub health: f32,
    pub max_health: f32,
    pub gold: u32,
    pub gems: u32,
    pub ally_tributed: u32,
    pub enemy_tributed: u32,
    /// Counts indexed by SDK item id.
    pub items: [u8; ITEM_TYPES],
}

#[derive(Clone, Debug, PartialEq)]
pub struct Ledger {
    pub me: ChampionKind,
    pub round: u32,
    pub gold: u32,
    pub lifetime_gold: u32,
    pub gems: u32,
    pub ally_tributed: u32,
    pub enemy_tributed: u32,
    pub deaths: u32,
    pub items: [u8; ITEM_TYPES],
    pub hp_frac: f32,
    alive: bool,
    spent_since_obs: u32,
    refunded_since_obs: u32,
    seen: bool,
}

impl Ledger {
    #[must_use]
    pub fn new(me: ChampionKind) -> Self {
        Self {
            me,
            round: 0,
            gold: 0,
            lifetime_gold: 0,
            gems: 0,
            ally_tributed: 0,
            enemy_tributed: 0,
            deaths: 0,
            items: [0; ITEM_TYPES],
            hp_frac: 1.0,
            alive: true,
            spent_since_obs: 0,
            refunded_since_obs: 0,
            seen: false,
        }
    }

    /// The executor calls this after every successful purchase.
    pub fn record_spend(&mut self, gold: u32) {
        self.spent_since_obs += gold;
    }

    /// Tavi's sales refund gold, which the rules say is not earned gold.
    pub fn record_refund(&mut self, gold: u32) {
        self.refunded_since_obs += gold;
    }

    pub fn observe(&mut self, obs: &SelfObs) {
        if self.seen {
            let expected = self.gold.saturating_sub(self.spent_since_obs) + self.refunded_since_obs;
            self.lifetime_gold += obs.gold.saturating_sub(expected);
            if self.alive && !obs.alive {
                self.deaths += 1;
            }
        } else {
            self.lifetime_gold = obs.gold;
            self.seen = true;
        }
        self.spent_since_obs = 0;
        self.refunded_since_obs = 0;
        self.round = obs.round;
        self.alive = obs.alive;
        self.gold = obs.gold;
        self.gems = obs.gems;
        self.ally_tributed = obs.ally_tributed;
        self.enemy_tributed = obs.enemy_tributed;
        self.items = obs.items;
        self.hp_frac = if obs.max_health > 0.0 { obs.health / obs.max_health } else { 0.0 };
    }

    #[must_use]
    pub fn alive(&self) -> bool {
        self.alive
    }

    /// Shards of this family/stat toward the next emblem (0..5).
    #[must_use]
    pub fn shard_progress(&self, family: Family, stat: Stat) -> u8 {
        self.items[item_id(family, stat, false) as usize]
    }

    #[must_use]
    pub fn emblems(&self, family: Family) -> u8 {
        Stat::ALL.iter().map(|&s| self.items[item_id(family, s, true) as usize]).sum()
    }

    /// Total shards bought for a stat, counting those inside emblems.
    #[must_use]
    pub fn total_shards(&self, stat: Stat) -> u32 {
        Family::ALL
            .iter()
            .map(|&f| {
                u32::from(self.shard_progress(f, stat))
                    + u32::from(self.items[item_id(f, stat, true) as usize])
                        * f.stat_shards_per_emblem()
            })
            .sum()
    }

    /// Gems still needed by our team to win outright.
    #[must_use]
    pub fn gems_to_win(&self, winning_gems: u32) -> u32 {
        winning_gems.saturating_sub(self.ally_tributed)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn obs(round: u32, gold: u32, gems: u32, alive: bool) -> SelfObs {
        SelfObs {
            round,
            alive,
            health: 500.0,
            max_health: 1000.0,
            gold,
            gems,
            ally_tributed: 0,
            enemy_tributed: 0,
            items: [0; ITEM_TYPES],
        }
    }

    #[test]
    fn item_ids_match_sdk_enum_order() {
        assert_eq!(item_id(Family::Monster, Stat::Strength, false), 0);
        assert_eq!(item_id(Family::Monster, Stat::Health, true), 5);
        assert_eq!(item_id(Family::Power, Stat::Strength, false), 6);
        assert_eq!(item_id(Family::Jungle, Stat::Focus, true), 27);
        assert_eq!(item_id(Family::Bruiser, Stat::Health, true), 41);
        assert_eq!(item_id(Family::Tribute, Stat::Strength, false), 42);
        assert_eq!(item_id(Family::Greed, Stat::Health, true), 77);
        assert_eq!(item_id(Family::Collectors, Stat::Health, true), 83);
        for id in 0..ITEM_TYPES as u8 {
            let (f, s, e) = decode_item(id).unwrap();
            assert_eq!(item_id(f, s, e), id);
        }
        assert!(decode_item(84).is_none());
    }

    #[test]
    fn lifetime_gold_counts_income_not_spending() {
        let mut l = Ledger::new(ChampionKind::Varg);
        l.observe(&obs(1, 0, 0, true));
        l.observe(&obs(2, 90, 0, true)); // wolf camp
        l.record_spend(60); // two shards
        l.observe(&obs(3, 30, 0, true));
        l.observe(&obs(4, 80, 0, true)); // +50 kill gold
        assert_eq!(l.lifetime_gold, 140);
        assert_eq!(l.gold, 80);
        l.record_refund(30); // Tavi sells a shard
        l.observe(&obs(5, 110, 0, true));
        assert_eq!(l.lifetime_gold, 140, "refunds are not earned gold");
    }

    #[test]
    fn deaths_are_counted_on_alive_to_dead_transitions() {
        let mut l = Ledger::new(ChampionKind::Ryth);
        l.observe(&obs(1, 0, 10, true));
        l.observe(&obs(2, 0, 0, false));
        l.observe(&obs(3, 0, 0, false));
        l.observe(&obs(4, 0, 0, true));
        assert_eq!(l.deaths, 1);
    }

    #[test]
    fn shard_totals_include_emblems() {
        let mut l = Ledger::new(ChampionKind::Ryth);
        let mut o = obs(1, 0, 0, true);
        o.items[item_id(Family::Jungle, Stat::Health, true) as usize] = 1;
        o.items[item_id(Family::Power, Stat::Health, true) as usize] = 1;
        o.items[item_id(Family::Monster, Stat::Health, false) as usize] = 2;
        l.observe(&o);
        assert_eq!(l.total_shards(Stat::Health), 5 + 6 + 2);
        assert_eq!(l.emblems(Family::Jungle), 1);
    }
}
